import {ReactionRateEngine,EquilibriumEngine} from './engines.js';
import {chart,apparatus,ParticleView,fmt,colors} from './visuals.js';
import {esc} from './state.js';
const sizes={chunk:'塊狀',grain:'顆粒',powder:'粉末'};
const rateLabel=p=>p.kind==='peroxide'?`MnO₂ ${p.catalyst} g`:`${sizes[p.size]} / ${p.mass} g / ${p.concentration} M / ${p.temperature}°C`;
const numberControl=(name,label,value,min,max,step=1)=>`<label class="field"><span>${label}</span><input type="range" name="${name}" min="${min}" max="${max}" step="${step}" value="${value}"><output for="${name}">${value}</output></label>`;
function ticker(host,callback){let old=performance.now(),acc=0,alive=true,visible=false;const obs=new IntersectionObserver(es=>visible=es[0].isIntersecting,{rootMargin:'150px'});obs.observe(host);function frame(now){if(!alive)return;const dt=Math.min(.12,(now-old)/1000);old=now;if(visible){acc+=dt;if(acc>=.08){callback(acc);acc=0;}}requestAnimationFrame(frame);}requestAnimationFrame(frame);return()=>{alive=false;obs.disconnect();};}
export function mountRateLab(host,id,state,{save,record,isUnlocked}){
 const dual=id!==2,kind=id===5?'peroxide':'carbonate';let config={kind,mass:1,concentration:1,size:'chunk',temperature:id===4?30:20,catalyst:id===5?1:0,...state.config};
 try{new ReactionRateEngine(config);}catch{config={kind,mass:1,concentration:1,size:'chunk',temperature:id===4?30:20,catalyst:id===5?1:0};}
 config.kind=kind;let engines=[],samples=[],histories=[],phase='setup',step=0,selected='',running=false,recorded=false;
 host.innerHTML=`<div class="lab-head"><div><small>REACTION RATE LAB / ${id===2?'01':id===4?'02':'03'}</small><h3>${id===2?'讓氣體，留下時間的證據':id===4?'同樣起點，不同溫度':'兩條路徑，同一個終點'}</h3></div><span class="lab-badge">可重複的對照實驗</span></div>
 <div class="lab-layout"><div class="bench-area"><div class="bench-sequence"><span>① 設定與秤量</span><span>② 分隔裝料、接管</span><span>③ 混合並計時</span></div><div class="reagent-rack" ${dual?'hidden':''}><button class="reagent" data-material="solid" draggable="true"><span class="reagent-icon stones">◈ ◇</span><b>碳酸鈣樣品</b><small>秤量後取用</small></button><button class="reagent" data-material="acid" draggable="true"><span class="reagent-icon vial">HCl</span><b>稀鹽酸 50 mL</b><small>裝進分隔小杯</small></button><p>先點選材料，再點瓶子；<br>也可拖曳到反應區。</p></div><div data-apparatus></div><button class="drop-target" data-load ${dual?'hidden':''}>選取碳酸鈣 → 放進反應瓶</button><div class="live-metrics" data-metrics></div><div class="chart-box" data-rate-chart></div></div>
 <section class="lab-controls" aria-label="${id} 號實驗控制"><span class="step-label">${dual?'固定材料，只改一項':'先設計你的對照'}</span><fieldset data-config><legend class="sr-only">實驗條件</legend>${id===2?`<label class="field"><span>碳酸鈣顆粒</span><select name="size">${Object.entries(sizes).map(([k,v])=>`<option value="${k}" ${config.size===k?'selected':''}>${v}</option>`).join('')}</select></label>${numberControl('mass','碳酸鈣質量 / g',config.mass,.5,2,.5)}${numberControl('concentration','鹽酸濃度 / mol/L',config.concentration,.1,1,.1)}`:id===4?`${numberControl('temperature','比較組溫度 / °C',config.temperature,20,40,10)}<p class="fixed-vars">對照組 20°C<br>兩組：1 g 塊狀 CaCO₃<br>1 M 稀鹽酸 50 mL</p>`:`${numberControl('catalyst','比較組 MnO₂ / g',config.catalyst,0,2,.5)}<p class="fixed-vars">對照組：無催化劑<br>兩組：10 mmol H₂O₂、20°C<br>黑色粉末前後皆保留</p>`}</fieldset>
 <p class="condition-note" data-condition></p><button class="secondary" data-prepare ${dual?'':'hidden'}>裝好兩組相同材料</button><button class="primary" data-start>${dual?'混合兩組並計時':'混合並開始計時'} <span>→</span></button><div class="button-row"><button class="secondary" data-pause disabled>暫停</button><button class="secondary" data-step disabled>前進 30 秒</button></div><button class="text-button" data-reset>↺ 清空裝置，再做一組</button><p class="observation-status" data-status role="status"></p><p class="micro-note">播放為 8 倍模型時間。暫停可讀數；前進 30 秒仍逐模型計算。</p>
 <div class="evidence-tip">${id===2?'任務順序：① 1 g 塊狀＋1 M 酸；② 1 g 粉末＋1 M 酸；③ 1 g 粉末＋0.5 M 酸。每組反應完成會自動存入紀錄。':id===4?'把比較組設為 30°C 或 40°C，等兩組都完成，確認相同的平台值。':'比較組加入 0.5～2 g MnO₂，等兩組都完成，檢查相同的氧氣總量。'}</div></section></div>
 ${id===4?'<div class="particle-pair"><div><b>20°C 粒子示意</b><canvas data-particles="0" aria-label="20°C 粒子運動"></canvas></div><div><b data-temp-title>比較組粒子示意</b><canvas data-particles="1" aria-label="比較組粒子運動"></canvas></div></div>':''}
 ${id===5?`<div class="energy-diagram"><svg viewBox="0 0 660 175" role="img" aria-label="催化劑降低能量障礙，起點與終點的能量不變"><path d="M40 15V145H630" fill="none" stroke="#859780"/><path d="M55 115C140 115 160 20 280 22S420 135 600 135" fill="none" stroke="#ad7446" stroke-width="3"/><path d="M55 115C145 115 190 75 280 75S425 135 600 135" fill="none" stroke="#466f54" stroke-width="3"/><text x="205" y="17">沒有催化劑</text><text x="224" y="66">有催化劑</text><text x="60" y="139">反應物</text><text x="545" y="158">生成物</text><text x="590" y="116">反應進程 →</text></svg><p>越過比較低的「山丘」，反應通常更容易發生。這是能量障礙的定性示意，並非分子真的爬山。</p></div>`:''}
 <div class="record-sheet"><h4>觀察紀錄 <span>完成即保存 · 最近 12 筆</span></h4><div data-records></div></div><details class="model-note"><summary>模型條件與簡化假設</summary><p>密閉收集、不漏氣、不考慮氣體溶解；注射筒活塞可自由移動。氣體統一按 24 L/mol 換算（示意參考值）。碳酸鈣摩爾質量採 100 g/mol，依 1:2 計量關係限制產量；雙氧水採 2:1 生成氧氣。時間採可有限完成的簡化速率模型，不是真實實驗的校正秒數。反應物逐漸減少，反應會逐漸變慢。氣泡數為速率的視覺示意，不是逐顆氣體分子。${id===5?'催化劑量效應僅適用 0～2 g 的教學範圍。':''}本虛擬裝置將反應物先分隔，接妥氣路後才混合並同步計時。</p></details>`;
 const find=s=>host.querySelector(s);const views=id===4?[...host.querySelectorAll('canvas')].map(c=>new ParticleView(c)):[];
 const params=()=>dual?[{...config,temperature:20,catalyst:0},{...config}]:[{...config}];
 const init=()=>{engines=params().map(p=>new ReactionRateEngine(p));samples=engines.map(e=>e.sample());histories=samples.map(s=>[s]);};
 const notice=t=>find('[data-status]').textContent=t;
 function recordTable(){find('[data-records]').innerHTML=state.records.length?`<div class="table-scroll"><table><thead><tr><th>條件</th><th>最終量 / mL</th><th>達 90% / s</th><th>起始速率 / mL/s</th></tr></thead><tbody>${state.records.map(r=>`<tr><td>${esc(r.label)}</td><td>${fmt(r.final)}</td><td>${fmt(r.t90)}</td><td>${fmt(r.initialRate,2)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-note">還沒有完成的實驗。完成後，曲線也會帶到第 06 卡。</p>';}
 function evidence(){const rs=state.records;const equal=(a,b,keys)=>keys.every(k=>a.p[k]===b.p[k]);if(id===2){for(const a of rs)for(const b of rs){if(!a.p||!b.p)continue;const enough=r=>r.p.concentration*50>=r.p.mass*20;if(enough(a)&&enough(b)&&equal(a,b,['mass','concentration','temperature'])&&new Set([a.p.size,b.p.size]).has('chunk')&&new Set([a.p.size,b.p.size]).has('powder'))record('surface');if(enough(a)&&enough(b)&&equal(a,b,['mass','size','temperature'])&&a.p.concentration!==b.p.concentration)record('concentration');}}else if(id===4&&config.temperature>20)record('warm');else if(id===5&&config.catalyst>0)record('catalyst');}
 function completed(){if(recorded||!samples.every(s=>s.done))return;recorded=true;running=false;phase='done';engines.forEach(e=>state.records.push({label:rateLabel(e.p),p:e.p,final:e.sample().capacity,t90:e.timeFor(.9),initialRate:e.sample(0).rate,curve:e.curve(81).map(s=>({time:s.time,volume:s.volume,rate:s.rate}))}));state.records=state.records.slice(-12);evidence();save();recordTable();notice('✓ 本組反應完成，數據已保存。比較曲線的平台，再清空裝置改一項條件。');find('[data-pause]').disabled=true;find('[data-step]').disabled=true;find('[data-start]').disabled=true;}
 function draw(){find('[data-apparatus]').innerHTML=dual?`<div class="dual-bench">${engines.map((e,i)=>`<div><b>${i?'比較組':'對照組'} · ${id===4?e.p.temperature+'°C':e.p.catalyst?'有催化劑':'無催化劑'}</b>${apparatus({id:'r'+id+i,sample:samples[i],loaded:step>0,kind,temperature:e.p.temperature,catalyst:e.p.catalyst,mass:e.p.mass,time:e.time,label:i?'比較組':'對照組'})}</div>`).join('')}</div>`:apparatus({id:'r2',sample:samples[0],mass:config.mass,loaded:step>0,temperature:20,time:engines[0].time});
 find('[data-metrics]').innerHTML=samples.map((s,i)=>`<div><small>${dual?(i?'比較組':'對照組'):'CO₂ 累積量'}</small><strong>${fmt(s.volume)} <em>mL</em></strong><span>當下 ${fmt(s.rate,2)} mL/s${id===5?' · MnO₂ '+fmt(engines[i].p.catalyst)+' g':''}</span></div>`).join('')+`<div><small>理論最終量${id===2&&engines[0].initial.acid<engines[0].initial.carbonate*2?' · 酸不足':''}</small><strong>${fmt(samples[0].capacity)} <em>mL</em></strong><span>${id===2?'CaCO₃ 剩 '+fmt(samples[0].species.CaCO3/10,2)+' g':id===4?'同樣初始反應物':'同樣初始雙氧水'}</span></div>`;
 const old=id===2?state.records.slice(-2).filter(r=>r.curve?.length).map((r,i)=>({label:'前次：'+r.label,data:r.curve.map(p=>({x:p.time,y:p.volume})),color:colors[i+1],dashed:true})):[];
 find('[data-rate-chart]').innerHTML=chart([...histories.map((h,i)=>({label:dual?(i?'比較組':'對照組'):'本次實驗',data:h.map(s=>({x:s.time,y:s.volume})),color:colors[i]})),...old],{xMax:Math.max(...engines.map(e=>e.endTime),...old.flatMap(s=>s.data.map(p=>p.x))),yMax:Math.max(...samples.map(s=>s.capacity),...old.flatMap(s=>s.data.map(p=>p.y)),1)*1.1});
 views.forEach((v,i)=>v.draw({...samples[i],temperature:engines[i].p.temperature},{mode:'collision',concentration:1,surface:2}));}
 function reset(){running=false;phase='setup';step=0;selected='';recorded=false;find('[data-config]').disabled=false;find('[data-prepare]').disabled=false;find('[data-start]').disabled=false;find('[data-pause]').disabled=true;find('[data-step]').disabled=true;find('[data-pause]').textContent='暫停';host.querySelectorAll('[data-material]').forEach(b=>{b.disabled=false;b.setAttribute('aria-pressed','false');});find('[data-load]').disabled=false;find('[data-load]').textContent='選取碳酸鈣 → 放進反應瓶';init();draw();condition();notice('先設定條件，再依 ① → ② → ③ 完成實驗。');}
 function condition(){const e=engines[0];find('[data-condition]').textContent=id===2?`固定：20°C、酸 50 mL。${e.initial.acid<e.initial.carbonate*2?'酸不足！此組可觀察限制產量，但不能作為表面積任務的公平比較。':'酸足量，可用於表面積比較。'}`:id===4?'只有溫度不同；氣體都換算至同一參考條件。':'催化劑只改變途徑與速率，不供應氧氣。';if(id===4)find('[data-temp-title]').textContent=config.temperature+'°C 粒子示意';}
 host.querySelector('[data-config]').addEventListener('input',e=>{if(phase!=='setup')return;const input=e.target;if(!input.name)return;config[input.name]=input.tagName==='SELECT'?input.value:Number(input.value);input.parentElement.querySelector('output')?.replaceChildren(String(input.value));state.config={...config};save();init();draw();condition();});
 function take(material){if(!isUnlocked()){notice('請先在上方留下猜想。');return;}if(phase!=='setup')return;if(material==='acid'&&step!==1){notice('先把秤好的碳酸鈣放進反應瓶，再裝酸。');return;}if(material==='solid'&&step>0)return;selected=material;host.querySelectorAll('[data-material]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.material===selected)));find('[data-load]').textContent=material==='solid'?'將秤好的 '+config.mass+' g 碳酸鈣放入瓶底':'把 50 mL 稀鹽酸裝進分隔小杯';notice('已選取材料。點反應區放入，或拖曳到反應區。');}
 host.querySelectorAll('[data-material]').forEach(b=>{b.addEventListener('click',()=>take(b.dataset.material));b.addEventListener('dragstart',e=>{take(b.dataset.material);e.dataTransfer.setData('text/plain',b.dataset.material);});});
 function load(){if(!selected){notice('請先選取要使用的材料。');return;}if(selected==='solid'&&step===0){step=1;find('[data-config]').disabled=true;find('[data-material="solid"]').disabled=true;notice('碳酸鈣已秤量入瓶。接著選取稀鹽酸，裝入分隔小杯。');find('[data-load]').textContent='接著選取稀鹽酸';}else if(selected==='acid'&&step===1){step=2;find('[data-material="acid"]').disabled=true;find('[data-load]').disabled=true;notice('反應物已分隔放置，氣路接妥。按「混合並開始計時」。');}selected='';draw();}
 find('[data-load]').addEventListener('click',load);find('[data-load]').addEventListener('dragover',e=>e.preventDefault());find('[data-load]').addEventListener('drop',e=>{e.preventDefault();load();});
 find('[data-prepare]').addEventListener('click',()=>{if(!isUnlocked())return;step=2;find('[data-config]').disabled=true;find('[data-prepare]').disabled=true;draw();notice('兩組已秤量、分隔裝料並接妥注射筒，準備同步混合。');});
 find('[data-start]').addEventListener('click',()=>{if(!isUnlocked())return;if(step!==2){notice(dual?'先裝好兩組相同材料。':'先完成碳酸鈣與酸的分隔裝料。');return;}if(phase!=='setup')return;phase='running';running=true;find('[data-start]').disabled=true;find('[data-pause]').disabled=false;find('[data-step]').disabled=false;notice('反應中：比較同一時間的氣體量，也記得觀察最後的平台。');});
 function advance(dt){samples=engines.map(e=>e.advance(dt));samples.forEach((s,i)=>{histories[i].push(s);if(histories[i].length>180)histories[i]=histories[i].filter((_,j)=>j%2===0||j===histories[i].length-1);});draw();completed();}
 find('[data-pause]').addEventListener('click',()=>{running=!running;find('[data-pause]').textContent=running?'暫停':'繼續';});find('[data-step]').addEventListener('click',()=>{if(phase==='running')advance(30);});find('[data-reset]').addEventListener('click',reset);
 reset();recordTable();return ticker(host,dt=>{if(running&&isUnlocked())advance(dt*8);});
}

export function mountEquilibriumLab(host,id,state,{save,record,isUnlocked}){
 const challenge=id===9;let engine,comparison=null,history=[],comparisonHistory=[],running=false,view='macro',pending='',stored=false,dirty=false;
 host.innerHTML=`<div class="lab-head"><div><small>DYNAMIC EQUILIBRIUM / ${challenge?'05':'04'}</small><h3>${challenge?'給平衡，一個新的條件':'外表安靜，裡面忙碌'}</h3></div><span class="lab-badge">固定體積 · 密閉模型</span></div><div class="equilibrium-equation"><span class="no2-dot"></span> 2NO₂(g) <b>⇌</b> N₂O₄(g) ${challenge?'+ 熱':''}<small>紅棕色　　近乎無色</small></div>
 <div class="lab-layout equilibrium-layout"><div class="bench-area"><div class="view-tabs" role="group" aria-label="觀察視角"><button data-view="macro" aria-pressed="true">宏觀顏色</button><button data-view="micro" aria-pressed="false">微觀粒子</button></div><div class="equilibrium-scene"><div data-macro class="sealed-scene"><div class="glass-cabinet"><div class="sealed-flask"><div class="gas-color"></div><i></i><span>密閉 · 1 L</span></div></div><p>顏色深淺對應 NO₂ 濃度</p></div><div data-micro hidden><canvas aria-label="NO₂ 與 N₂O₄ 粒子運動，持續呈現雙向反應"></canvas><div class="micro-key"><span>● NO₂</span><span>●● N₂O₄</span></div><p>粒子數經比例取整；原子守恆以計算讀數為準。運動路徑是示意。</p></div></div><div class="live-metrics" data-metrics></div><div class="reaction-flows" data-flows></div><div data-concentration-chart class="chart-box"></div><div data-speed-chart class="chart-box"></div></div>
 <section class="lab-controls"><span class="step-label">${challenge?'從已建立的平衡開始':'選擇同原子總量的起點'}</span>${challenge?`<p class="fixed-vars">基準：25°C、固定 1 L<br>生成 N₂O₄ 的正方向放熱</p><button class="secondary" data-add>定量注入 NO₂ ＋0.40 mol/L</button><label class="field"><span>溫度 / °C</span><select data-temperature><option value="25">25°C · 基準</option><option value="40">40°C · 升溫</option><option value="10">10°C · 降溫</option></select></label><button class="secondary" data-catalyst>比較假想催化劑 ×4</button><p class="micro-note">催化比較會另開同起點的兩條模型曲線；這是假想理想催化劑，不表示此氣體有可用的實作催化劑。</p>`:`<label class="field"><span>起始組成 / mol/L</span><select data-initial><option value="a">NO₂ 2.00 / N₂O₄ 0</option><option value="mixed">NO₂ 1.60 / N₂O₄ 0.20</option><option value="b">NO₂ 0 / N₂O₄ 1.00</option></select></label><p class="fixed-vars">固定 25°C、1 L<br>NO₂ ＋ 2×N₂O₄＝2.00<br>所有起點的氮原子總量相同</p>`}<button class="primary" data-play>${challenge?'觀察平衡中的雙向反應':'開始模擬'} <span>→</span></button><button class="secondary" data-step>前進 30 秒</button><button class="text-button" data-reset>↺ 重設並重播</button><p class="observation-status" data-status role="status"></p><div data-comparison></div><div class="evidence-tip">${challenge?'依序完成：① 注入後的新平衡；② 40°C；③ 10°C；④ 假想催化比較。每次操作後，前進時間直到新平衡建立。':'開始後觀察兩個速率趨於相等，再切換微觀視角。可用「前進 30 秒」縮短等待。'}</div><p class="virtual-only">NO₂ 有毒，本章僅使用虛擬模型；不要自行操作此氣體。</p></section></div><div class="record-sheet"><h4>平衡觀察紀錄</h4><div data-equilibrium-records></div></div><details class="model-note"><summary>計算規則、計量與簡化假設</summary><p>固定 1 L，封閉系統（注入瞬間除外），僅模擬 2NO₂ ⇌ N₂O₄。正反應事件速率＝k正 × [NO₂]²，逆反應事件速率＝k逆 × [N₂O₄]。每一次淨正向轉換消耗 2 份 NO₂、生成 1 份 N₂O₄；[NO₂]＋2[N₂O₄] 保持不變，注入時依加入量增加。25°C 使用 k正＝0.12、k逆＝0.06；每升 10°C 分別乘 1.35 與 2.1，使升溫偏向 NO₂。催化模型將兩係數同乘 4。這些數值為教學設定，不是真實氣體的定量預測。速率單位為 mol/(L·s)，均按反應式事件數表示；NO₂ 消耗量速率為正向事件速率的兩倍。以正逆速率相對差小於 0.1% 標示「接近平衡」。此公式是模型說明，不列為國中必學計算。</p></details>`;
 const find=s=>host.querySelector(s),pv=new ParticleView(find('canvas'));
 const notice=t=>find('[data-status]').textContent=t;
 function table(){find('[data-equilibrium-records]').innerHTML=state.records.length?`<div class="table-scroll"><table><thead><tr><th>觀察</th><th>NO₂ / M</th><th>N₂O₄ / M</th><th>正向速率</th><th>逆向速率</th></tr></thead><tbody>${state.records.map(r=>`<tr><td>${esc(r.label)}</td><td>${fmt(r.no2,3)}</td><td>${fmt(r.n2o4,3)}</td><td>${fmt(r.forward,4)}</td><td>${fmt(r.reverse,4)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-note">建立平衡後，讀數會自動留下。</p>';}
 function init(){const v=find('[data-initial]')?.value;const start=v==='b'?{no2:0,n2o4:1}:v==='mixed'?{no2:1.6,n2o4:.2}:{no2:2,n2o4:0};engine=challenge?EquilibriumEngine.balanced({no2:2,n2o4:0}):new EquilibriumEngine(start);comparison=null;comparisonHistory=[];history=[engine.sample()];stored=false;dirty=false;pending='';running=false;find('[data-play]').textContent=challenge?'觀察平衡中的雙向反應':'開始模擬';if(challenge)find('[data-temperature]').value='25';if(!challenge)find('[data-initial]').disabled=false;notice(challenge?'25°C 的平衡已準備好。選擇一種改變，追蹤新的結果。':'先選起始組成，再開始模擬。');draw();}
 function draw(){const s=engine.sample();find('.gas-color').style.background=`rgba(139,65,29,${Math.min(.85,.07+s.no2*.31)})`;find('[data-metrics]').innerHTML=`<div><small>NO₂ / mol/L</small><strong>${fmt(s.no2,3)}</strong><span>紅棕色</span></div><div><small>N₂O₄ / mol/L</small><strong>${fmt(s.n2o4,3)}</strong><span>近乎無色</span></div><div><small>${s.temperature}°C · ${fmt(s.time)} s</small><strong class="status-word">${s.equilibrated?'接近平衡':'正在改變'}</strong><span>氮原子濃度 ${fmt(s.units,2)} mol/L</span></div>`;
 find('[data-flows]').innerHTML=`<div><span>正反應 →</span><b>${fmt(s.forward,4)}</b><small>mol/(L·s)</small><i style="width:${Math.min(100,s.forward*300)}%"></i></div><div><span>← 逆反應</span><b>${fmt(s.reverse,4)}</b><small>mol/(L·s)</small><i style="width:${Math.min(100,s.reverse*300)}%"></i></div><p>持續轉換的累積量：正向 ${fmt(s.forwardEvents,2)} / 逆向 ${fmt(s.reverseEvents,2)} mol/L</p>`;
 const series=[{label:'NO₂',data:history.map(p=>({x:p.time,y:p.no2})),color:colors[1]},{label:'N₂O₄',data:history.map(p=>({x:p.time,y:p.n2o4})),color:colors[0]}];if(comparison)series.push({label:'有催化劑的 NO₂',data:comparisonHistory.map(p=>({x:p.time,y:p.no2})),color:colors[2],dashed:true});find('[data-concentration-chart]').innerHTML=chart(series,{yLabel:'濃度 / mol/L',height:220});find('[data-speed-chart]').innerHTML=chart([{label:'正反應速率',data:history.map(p=>({x:p.time,y:p.forward})),color:colors[1]},{label:'逆反應速率',data:history.map(p=>({x:p.time,y:p.reverse})),color:colors[0]}],{yLabel:'反應事件速率 / mol/(L·s)',height:205});
 pv.draw(s);if(comparison){const c=comparison.sample();find('[data-comparison]').innerHTML=`<div class="comparison-status"><b>同溫、同起點的比較</b><p>無催化：${s.equilibrated?'已接近平衡':'還在接近'}<br>有催化：${c.equilibrated?'已接近平衡':'還在接近'}</p><p>有催化讀數：NO₂ ${fmt(c.no2,3)} / N₂O₄ ${fmt(c.n2o4,3)} M</p><small>兩組理論平衡：NO₂ ${fmt(engine.equilibrium().no2,3)} M</small></div>`;}else find('[data-comparison]').innerHTML='';}
 function check(){const s=engine.sample();if(!s.equilibrated||s.time===0)return;if(!challenge){record('equilibrium');if(view==='micro')record('micro');}else if(pending&&(!comparison||comparison.sample().equilibrated)){record(pending);pending='';dirty=false;}
 if(!stored&&(!comparison||comparison.sample().equilibrated)){stored=true;state.records.push({label:comparison?'假想催化劑比較':challenge?`${s.temperature}°C / 原子總量 ${fmt(s.units,2)}`:'起始 '+find('[data-initial]').selectedOptions[0].textContent,...s,curve:history.map(p=>({time:p.time,no2:p.no2,n2o4:p.n2o4,forward:p.forward,reverse:p.reverse}))});state.records=state.records.slice(-12);save();table();notice('✓ 已接近平衡：兩個方向仍在進行。讀數與曲線已保存。');}}
 function advance(dt){const pieces=Math.max(1,Math.ceil(dt/.5));for(let i=0;i<pieces;i++){history.push(engine.advance(dt/pieces));if(comparison)comparisonHistory.push(comparison.advance(dt/pieces));}if(history.length>260)history=history.filter((_,i)=>i%2===0||i===history.length-1);if(comparisonHistory.length>260)comparisonHistory=comparisonHistory.filter((_,i)=>i%2===0||i===comparisonHistory.length-1);check();draw();}
 function play(){if(!isUnlocked())return;running=!running;find('[data-play]').textContent=running?'暫停模擬':'繼續模擬';if(!challenge)find('[data-initial]').disabled=true;}
 find('[data-play]').addEventListener('click',play);find('[data-step]').addEventListener('click',()=>{if(!isUnlocked())return;if(!challenge)find('[data-initial]').disabled=true;advance(30);});find('[data-reset]').addEventListener('click',init);find('[data-initial]')?.addEventListener('change',init);
 host.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;host.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));find('[data-macro]').hidden=view!=='macro';find('[data-micro]').hidden=view!=='micro';check();draw();}));
 function mayChange(){if(!isUnlocked())return false;if(dirty&&!engine.sample().equilibrated){notice('先觀察這次的新平衡；可按「前進 30 秒」縮短等待，再改下一項。');return false;}comparison=null;comparisonHistory=[];stored=false;return true;}
 function changeStart(task){pending=task;dirty=true;history.push(engine.sample());running=true;find('[data-play]').textContent='暫停模擬';draw();}
 find('[data-add]')?.addEventListener('click',()=>{if(!mayChange())return;try{history.push(engine.sample());engine.addNO2(.4);changeStart('add');notice('注入瞬間只有 NO₂ 跳升；接著觀察 N₂O₄ 如何逐漸改變。');}catch(e){notice(e.message);}});
 find('[data-temperature]')?.addEventListener('change',e=>{if(!mayChange()){e.target.value=String(engine.temperature);return;}history.push(engine.sample());engine.setConditions({temperature:Number(e.target.value)});changeStart(engine.temperature>25?'heat':engine.temperature<25?'cool':'');notice('濃度不會瞬間跳到新平衡，但兩個速率立即改變。觀察接下來的組成。');});
 find('[data-catalyst]')?.addEventListener('click',()=>{if(!mayChange())return;const temperature=engine.temperature,units=engine.units;engine=new EquilibriumEngine({no2:units,n2o4:0,temperature});comparison=new EquilibriumEngine({no2:units,n2o4:0,temperature,catalyst:4});history=[engine.sample()];comparisonHistory=[comparison.sample()];changeStart('cat');notice('新比較從相同 NO₂ 起點開始。催化組更快，但最後應到同一組成。');});
 init();table();return ticker(host,dt=>{if(running&&isUnlocked())advance(dt*4);});
}
